                "benoit-1895-b-chain",
                "clarke-foot",
                "clarke-link",
                "clarke-yard",
                "foot",
                "gold-coast-foot",
                "indian-1937-yard",
                "indian-yard",
                "meter",
                "sears-1922-truncated-chain",
                "sears-chain",
                "sears-foot",
                "sears-yard",
                "us-foot"
            ]
        },
